USE saudi_ecommerce;
-- Annual performance; only Delivered orders counted as sales.
SELECT YEAR(order_date) yr,COUNT(*) order_count,SUM(order_status='Delivered') delivered_orders,ROUND(SUM(CASE WHEN order_status='Delivered' THEN order_total_sar ELSE 0 END),2) delivered_sales_sar,ROUND(AVG(CASE WHEN order_status='Delivered' THEN order_total_sar END),2) delivered_aov_sar,ROUND(100*AVG(order_status='Cancelled'),2) cancellation_pct,ROUND(100*AVG(order_status='Returned'),2) return_pct FROM orders GROUP BY YEAR(order_date) ORDER BY yr;
WITH annual AS (SELECT YEAR(order_date) yr,COUNT(*) orders,SUM(CASE WHEN order_status='Delivered' THEN order_total_sar ELSE 0 END) sales FROM orders GROUP BY YEAR(order_date)) SELECT yr,orders,ROUND(sales,2) sales_sar,ROUND(100*(orders/LAG(orders) OVER (ORDER BY yr)-1),2) order_growth_pct,ROUND(100*(sales/LAG(sales) OVER (ORDER BY yr)-1),2) sales_growth_pct FROM annual ORDER BY yr;
SELECT c.city,COUNT(*) orders,ROUND(SUM(CASE WHEN o.order_status='Delivered' THEN o.order_total_sar ELSE 0 END),2) delivered_sales_sar,ROUND(100*AVG(o.order_status='Cancelled'),2) cancellation_pct FROM orders o JOIN customers c ON c.customer_id=o.customer_id GROUP BY c.city ORDER BY delivered_sales_sar DESC;
SELECT delivery_partner,SUM(delivery_status='Delivered') delivered_orders,ROUND(100*SUM(delivery_status='Delivered' AND actual_days>promised_days)/NULLIF(SUM(delivery_status='Delivered'),0),2) late_pct,ROUND(AVG(CASE WHEN delivery_status='Delivered' THEN delivery_cost_sar END),2) cost_per_delivered_sar FROM deliveries GROUP BY delivery_partner ORDER BY late_pct DESC;
SELECT p.category,ROUND(SUM(CASE WHEN o.order_status='Delivered' THEN i.line_revenue_sar ELSE 0 END),2) gross_item_sales_sar,ROUND(SUM(CASE WHEN o.order_status='Delivered' THEN i.line_revenue_sar-i.quantity*i.unit_cost_sar ELSE 0 END),2) pre_discount_item_margin_sar FROM order_items i JOIN orders o ON o.order_id=i.order_id JOIN products p ON p.product_id=i.product_id GROUP BY p.category ORDER BY gross_item_sales_sar DESC;
WITH frequency AS (SELECT customer_id,COUNT(*) orders FROM orders GROUP BY customer_id) SELECT CASE WHEN orders=1 THEN '1 order' WHEN orders=2 THEN '2 orders' WHEN orders<=5 THEN '3-5 orders' ELSE '6+ orders' END frequency_band,COUNT(*) customers,SUM(orders) orders FROM frequency GROUP BY frequency_band ORDER BY MIN(orders);
SELECT DATE_FORMAT(order_date,'%Y-%m') month,COUNT(*) orders,ROUND(SUM(CASE WHEN order_status='Delivered' THEN order_total_sar ELSE 0 END),2) delivered_sales_sar FROM orders GROUP BY DATE_FORMAT(order_date,'%Y-%m') ORDER BY month;
